 {tab==='Wallet'&&<Page title='Wallet management' subtitle='Your wallet ledger is credited only after an administrator verifies a deposit.'><div className='mb-6 grid gap-3 sm:grid-cols-2'><button type='button' onClick={()=>{setModal('withdraw');setAmount('');setWithdrawAddress('');setWithdrawCrypto(cryptoOptions[0]);}} className='flex items-center justify-center gap-2 rounded-xl border-2 border-slate-200 bg-white px-5 py-3.5 font-bold text-slate-900 shadow-sm hover:border-indigo-300 hover:bg-indigo-50'><ArrowUpFromLine size={18} className='text-indigo-600'/>Withdraw funds</button><button type='button' onClick={()=>document.getElementById('deposit-funds')?.scrollIntoView({behavior:'smooth',block:'start'})} className='flex items-center justify-center gap-2 rounded-xl bg-indigo-600 px-5 py-3.5 font-bold text-white shadow-sm hover:bg-indigo-700'><Plus size={18}/>Deposit funds</button></div><div className='grid gap-4 sm:grid-cols-3'><Info title='Available balance' value={usd(balance)} icon={<Wallet/>}/><Info title='Invested' value={usd(invested)} icon={<BarChart3/>}/><Info title='Pending' value={usd(tx.filter(t=>t.status==='Pending').reduce((s,t)=>s+Number(t.amount||0),0))} icon={<CircleDollarSign/>}/></div><div id='deposit-funds' className='mt-6 rounded-2xl border bg-white p-6 shadow-sm'><h2 className='font-bold'>Crypto deposit options</h2><p className='mt-2 text-sm leading-6 text-slate-500'>Select a cryptocurrency, copy the wallet address, send your funds on the correct network, then submit the transaction hash below for administrator verification.</p><div className='mt-5 grid gap-4 md:grid-cols-3'>{cryptoOptions.map(opt=><div key={opt.id} onClick={()=>setSelectedCrypto(opt)} className={`cursor-pointer rounded-2xl border-2 p-4 transition ${selectedCrypto.id===opt.id?'border-indigo-500 bg-indigo-50/50':'border-slate-200 hover:border-slate-300'}`}><div className='flex items-center justify-between'><div className='flex items-center gap-3'><img src={opt.icon} alt={opt.symbol} className='h-11 w-11 rounded-full object-cover shadow-sm'/><div><div className='font-black'>{opt.name}</div><div className='text-xs text-slate-500'>{opt.network}</div></div></div>{selectedCrypto.id===opt.id&&<div className='rounded-full bg-indigo-600 p-1 text-white'><Check size={14}/></div>}</div><div className='mt-4 break-all rounded-xl bg-slate-50 p-3 font-mono text-xs leading-5 text-slate-700'>{opt.address}</div><button type='button' onClick={e=>{e.stopPropagation();copyAddress(opt);}} className={`mt-3 flex w-full items-center justify-center gap-2 rounded-xl border px-3 py-2.5 text-sm font-bold transition ${copiedId===opt.id?'border-emerald-300 bg-emerald-50 text-emerald-700':'border-slate-200 bg-white hover:bg-slate-50'}`}>{copiedId===opt.id?<><Check size={16}/>Copied</>:<><Copy size={16}/>Copy address</>}</button></div>)}</div><div className='mt-6 rounded-xl border border-indigo-100 bg-indigo-50/60 p-4'><div className='text-xs font-bold uppercase tracking-wider text-indigo-600'>Selected for deposit</div><div className='mt-1 font-black'>{selectedCrypto.name} · {selectedCrypto.network}</div><div className='mt-2 break-all font-mono text-sm text-slate-700'>{selectedCrypto.address}</div></div><div className='mt-5 grid gap-3 sm:grid-cols-2'><input value={deposit.name} onChange={e=>setDeposit({...deposit,name:e.target.value})} placeholder='Full name' className='rounded-xl border px-4 py-3'/><input value={deposit.email} onChange={e=>setDeposit({...deposit,email:e.target.value})} placeholder='Account email' className='rounded-xl border px-4 py-3'/><input type='number' min='0' step='0.01' value={deposit.amount} onChange={e=>setDeposit({...deposit,amount:e.target.value})} placeholder='Amount sent' className='rounded-xl border px-4 py-3'/><input value={deposit.txHash} onChange={e=>setDeposit({...deposit,txHash:e.target.value})} placeholder='Blockchain transaction hash' className='rounded-xl border px-4 py-3'/></div><button onClick={submitDeposit} className='mt-4 rounded-xl bg-indigo-600 px-5 py-3 font-bold text-white'>Submit deposit for review</button></div></Page>}
 {tab==='Transactions'&&<Page title='Transaction history' subtitle='Only transactions recorded for your account are shown.'><div className='mb-4 flex flex-col gap-3 sm:flex-row'><div className='flex flex-1 items-center gap-2 rounded-xl border bg-white px-3'><Search size={17} className='text-slate-400'/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder='Search transactions' className='w-full bg-transparent py-3 outline-none'/></div><select value={filter} onChange={e=>setFilter(e.target.value)} className='rounded-xl border bg-white px-4 py-3 text-sm font-semibold'><option>All</option><option>Deposit</option><option>Investment</option><option>Withdrawal</option></select></div><div className='overflow-hidden rounded-2xl border bg-white shadow-sm'>{tx.filter(t=>(filter==='All'||t.type===filter)&&`${t.type} ${t.reference||''}`.toLowerCase().includes(search.toLowerCase())).length===0?<Empty title='No matching transactions' text='Transactions will appear here as account activity is recorded.'/>:<div className='divide-y'>{tx.filter(t=>(filter==='All'||t.type===filter)&&`${t.type} ${t.reference||''}`.toLowerCase().includes(search.toLowerCase())).map((t,i)=><div key={i} className='grid gap-2 p-5 sm:grid-cols-5'><b>{t.type}</b><span className='text-slate-500'>{new Date(t.created_at).toLocaleDateString()}</span><b>{usd(Number(t.amount))}</b><span className='text-slate-500'>{t.reference||'Account activity'}</span><span className='text-sm font-bold'>{t.status}</span></div>)}</div>}</div></Page>}
 {tab==='Referrals'&&<Page title='Refer & earn' subtitle={`Earn ${referral?.referralPercent??settings?.referralPercent??5}% of your referral's first verified deposit.`}>{!referral?<div className='rounded-2xl border bg-white p-8 text-slate-500'>Loading referral program…</div>:<div className='space-y-5'><div className='grid gap-4 sm:grid-cols-3'><Info title='Your referrals' value={String(referral.referrals||0)} icon={<Users/>}/><Info title='Rewards paid' value={String(referral.rewardedCount||0)} icon={<Gift/>}/><Info title='Earnings' value={usd(Number(referral.earnings||0))} icon={<CircleDollarSign/>}/></div><div className='rounded-2xl border bg-white p-6 shadow-sm'><h2 className='font-black'>Your referral link</h2><p className='mt-2 text-sm text-slate-500'>Share this link. When someone joins and completes their first verified deposit, you earn {referral.referralPercent}% of that deposit as a wallet credit.</p><div className='mt-4 rounded-xl bg-slate-50 p-4 font-mono text-sm break-all'>{typeof window!=='undefined'?`${window.location.origin}${window.location.pathname}?ref=${referral.code}`:`?ref=${referral.code}`}</div><div className='mt-3 flex flex-wrap gap-2'><button type='button' onClick={copyReferralLink} className='rounded-xl bg-indigo-600 px-4 py-2.5 text-sm font-bold text-white'>{copiedRef?'Copied':'Copy referral link'}</button><div className='rounded-xl border px-4 py-2.5 text-sm font-bold'>Code: {referral.code}</div></div></div>{!referral.referredBy&&<div className='rounded-2xl border bg-white p-6 shadow-sm'><h2 className='font-black'>Have a referral code?</h2><p className='mt-2 text-sm text-slate-500'>Link a referrer to your account before your first deposit. You can only do this once.</p><div className='mt-4 flex flex-col gap-3 sm:flex-row'><input value={refCodeInput} onChange={e=>setRefCodeInput(e.target.value.toUpperCase())} placeholder='Enter referral code' className='flex-1 rounded-xl border px-4 py-3 font-mono uppercase'/><button type='button' onClick={applyReferralCode} className='rounded-xl bg-slate-900 px-5 py-3 font-bold text-white'>Apply code</button></div></div>}{referral.referredBy&&<div className='rounded-2xl border border-emerald-100 bg-emerald-50 p-4 text-sm font-semibold text-emerald-800'>You joined with referral code <b>{referral.referredBy}</b>.</div>}<div className='rounded-2xl border bg-white p-6 shadow-sm'><h2 className='font-black'>Referral activity</h2>{!(referral.history||[]).length?<p className='mt-3 text-sm text-slate-500'>No referrals yet. Share your link to get started.</p>:<div className='mt-4 divide-y'>{(referral.history||[]).map((h:any,i:number)=><div key={i} className='flex flex-wrap items-center justify-between gap-2 py-3 text-sm'><div><b>{h.email||h.name||'Investor'}</b><div className='text-xs text-slate-400'>{h.created_at?new Date(h.created_at).toLocaleString():''}</div></div><div className='text-right'><div className='font-bold'>{h.status}</div>{h.reward!=null&&<div className='text-emerald-700'>{usd(Number(h.reward))}</div>}</div></div>)}</div>}</div></div>}</Page>}
 
 
 {tab==='Notifications'&&<Page title='Notifications' subtitle='Account updates and messages from the Pledge Invest team.'><div className='mb-5 rounded-2xl border bg-white p-5 shadow-sm'><div className='font-black'>Automated alerts</div><p className='mt-1 text-sm text-slate-500'>Enable browser push alerts for deposit credits, withdrawal updates and admin messages. Email alerts are sent when email delivery is configured by the platform.</p><button type='button' onClick={enablePushAlerts} className='mt-4 rounded-xl bg-indigo-600 px-4 py-2.5 text-sm font-bold text-white'>Enable browser alerts</button></div>{notifications.length===0?<Empty title='No notifications yet' text='When the administrator sends an update, it will appear here.'/>:<div className='space-y-3'>{notifications.map(n=><button key={n.id} type='button' onClick={()=>!n.read&&markNotifRead(n.id)} className={`w-full rounded-2xl border p-5 text-left shadow-sm ${n.read?'bg-white':'border-indigo-200 bg-indigo-50/40'}`}><div className='flex items-start justify-between gap-3'><div className='font-black'>{n.title}</div>{!n.read&&<span className='rounded-full bg-indigo-600 px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide text-white'>New</span>}</div><p className='mt-2 whitespace-pre-wrap text-sm leading-6 text-slate-600'>{n.body}</p><div className='mt-3 text-xs text-slate-400'>{n.created_at?new Date(n.created_at).toLocaleString():''}</div></button>)}</div>}</Page>}
 
